#!/usr/bin/env node
// Writes the Start here block in every templates/*/README.md.
// Created by @meta_alchemist (https://x.com/meta_alchemist).
// The block is the same shape everywhere: what it does, when to use it, setup, first prompt, example output.
// Re-run after a summary, skill list, setup prompt, or sample grade changes. Do not edit the block by hand.
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { whenToUse } from "./lib/when-to-use.mjs";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const BEGIN = "<!-- start:begin (generated by scripts/build-start-here.mjs; edit the script, not this block) -->";
const END = "<!-- start:end -->";
const LINK_BEGIN = "<!-- start-link:begin (generated by scripts/build-start-here.mjs; edit the script, not this block) -->";
const LINK_END = "<!-- start-link:end -->";

function read(p) {
  return fs.readFileSync(p, "utf8");
}

function setupPrompt(prompts) {
  const at = prompts.indexOf("## 1. Setup");
  if (at < 0) throw new Error("PROMPTS.md has no setup section");
  const m = prompts.slice(at).match(/```\r?\n([\s\S]*?)```/);
  if (!m) throw new Error("setup section has no fenced prompt");
  return m[1].trim();
}

function gradeExample(dir) {
  const r = spawnSync(process.execPath, ["engine/lens.mjs", "fixtures/good-pack.json"], {
    cwd: dir,
    encoding: "utf8",
  });
  if (r.status !== 0) throw new Error(`${dir}: lens failed\n${r.stderr}`);
  const j = JSON.parse(r.stdout);
  if (j.verdict == null || j.grade == null) throw new Error(`${dir}: grade record has no verdict`);
  const measured = j.coverage === 1 ? "with every line measured" : `with coverage ${j.coverage}`;
  return { verdict: j.verdict, grade: j.grade, measured };
}

function tick(names) {
  return names.map((n) => `\`${n}\``).join(", then ");
}

function block(man, howto, prompt, sample) {
  const engines = [
    ...man.skills.filter((s) => s.endsWith("-lens-engine")),
    ...man.skills.filter((s) => s.endsWith("-domain-engine")),
  ];
  const rest = man.skills.filter((s) => s !== man.gettingStarted && !engines.includes(s));
  const restSentence = rest.length ? ` Then save the rest: ${rest.map((s) => `\`${s}\``).join(", ")}.` : "";
  const when = whenToUse(man.slug, howto);
  const importNote = howto.includes("recipe.json");
  const setup = importNote
    ? `**Setup.** The share link is pending review. [HOW-TO-USE.md](HOW-TO-USE.md) also says you can import \`recipe.json\` into a bot editor.

<!-- TODO: founder: confirm whether Grok Bot has an import action for recipe.json. Until that is confirmed, use the paste steps, which are the path INSTALL.md documents. -->

If you do not see an import action, paste each \`SKILL.md\` from \`skills/\` into a Grok Bot chat and say: "Save this as a skill." Save ${tick(engines)} first, then \`${man.gettingStarted}\`.${restSentence} Paste each fact in [MEMORY.md](MEMORY.md) and say: "Remember this for this project." Kit-wide steps: [INSTALL.md](../../INSTALL.md).`
    : `**Setup.** The Grok Bot share link is pending review, so there is no link to open. Paste each \`SKILL.md\` from \`skills/\` into a Grok Bot chat and say: "Save this as a skill." Save ${tick(engines)} first, then \`${man.gettingStarted}\`.${restSentence} Paste each fact in [MEMORY.md](MEMORY.md) and say: "Remember this for this project." Step by step: [HOW-TO-USE.md](HOW-TO-USE.md). The same files work in Cursor, Claude Code, Codex, or Gemini CLI. See [INSTALL.md](../../INSTALL.md).`;

  return `## Start here

**What it does.** ${man.summary}

**When to use it.** ${when}

${setup}

**First prompt.** Copy this into the chat after the skills are saved. Fill in the angle brackets.

\`\`\`
${prompt}
\`\`\`

**Example output.** From this folder:

\`\`\`
node engine/lens.mjs fixtures/good-pack.json
\`\`\`

The synthetic worked example prints verdict **${sample.verdict}** and grade **${sample.grade}/100**, ${sample.measured}. \`fixtures/good-pack.json\` is not a measurement of a real game.`;
}

function upsertMarked(text, begin, end, body, headingRe) {
  const wrapped = `${begin}\n${body.trim()}\n${end}\n`;
  if (text.includes(begin) && text.includes(end)) {
    const re = new RegExp(`${begin.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}[\\s\\S]*?${end.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\n?`);
    return text.replace(re, wrapped);
  }
  const idx = text.search(headingRe);
  if (idx < 0) return `${text.trimEnd()}\n\n${wrapped}`;
  return `${text.slice(0, idx)}${wrapped}\n${text.slice(idx)}`;
}

function upsert(readme, body) {
  const wrapped = `${BEGIN}\n${body.trim()}\n${END}\n`;
  if (readme.includes(BEGIN) && readme.includes(END)) {
    const re = new RegExp(`${BEGIN.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}[\\s\\S]*?${END.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\n?`);
    return readme.replace(re, wrapped);
  }
  const idx = readme.search(/^## /m);
  if (idx < 0) return `${readme.trimEnd()}\n\n${wrapped}`;
  return `${readme.slice(0, idx)}${wrapped}\n${readme.slice(idx)}`;
}

function upsertHowtoLink(howto) {
  return upsertMarked(
    howto,
    LINK_BEGIN,
    LINK_END,
    "Short version (what it does, setup, first prompt, example output): [Start here](README.md#start-here).",
    /^## (?:Install|Option A)/m,
  );
}

const dirs = fs.readdirSync(path.join(ROOT, "templates")).filter((d) => fs.existsSync(path.join(ROOT, "templates", d, "template.json"))).sort();
for (const slug of dirs) {
  const dir = path.join(ROOT, "templates", slug);
  const man = JSON.parse(read(path.join(dir, "template.json")));
  const howtoPath = path.join(dir, "HOW-TO-USE.md");
  const howto = read(howtoPath);
  const next = upsert(
    read(path.join(dir, "README.md")),
    block(man, howto, setupPrompt(read(path.join(dir, "PROMPTS.md"))), gradeExample(dir)),
  );
  fs.writeFileSync(path.join(dir, "README.md"), next);
  fs.writeFileSync(howtoPath, upsertHowtoLink(howto));
  console.log(`start-here: ${slug}`);
}
